<script setup lang="ts">
import { Form, Head, Link, router } from '@inertiajs/vue3'; import { computed, ref } from 'vue'; import { PackagePlus, Pencil, Plus, Search, Trash2, X } from '@lucide/vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label';
type I={id:number;name:string;price:string|number;stock:number}; type L={url:string|null;label:string;active:boolean}; type P={addOns:{data:I[];current_page:number;last_page:number;total:number;links:L[]};filters:{search:string};stats:{total:number;stock:number}}; const props=defineProps<P>(); const show=ref(false),editing=ref<I|null>(null),key=ref(0),search=ref(props.filters.search??''); const title=computed(()=>editing.value?'Edit add-on':'Add new add-on'),action=computed(()=>editing.value?`/add-ons/${editing.value.id}`:'/add-ons'),method=computed(()=>editing.value?'put':'post'); function create(){editing.value=null;key.value++;show.value=true} function edit(x:I){editing.value=x;key.value++;show.value=true} function close(){show.value=false;editing.value=null} function filter(){router.get('/add-ons',{search:search.value||undefined},{preserveState:true,replace:true})} function reset(){search.value='';filter()} function remove(x:I){if(confirm(`Hapus ${x.name}?`))router.delete(`/add-ons/${x.id}`)} function money(v:string|number){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(v))}
</script><template><Head title="Add-ons"/><div class="space-y-6 p-4 md:p-6"><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-medium text-primary">Master Data</p><h1 class="mt-1 text-2xl font-semibold tracking-tight">Add-ons</h1><p class="mt-1 text-sm text-muted-foreground">Kelola item tambahan yang dapat ditambahkan ke transaksi.</p></div><Button @click="create"><Plus class="mr-2 size-4"/> Add add-on</Button></div><div class="grid gap-3 sm:grid-cols-2"><div class="rounded-2xl border bg-card p-4 shadow-sm"><div class="flex justify-between"><span class="text-sm text-muted-foreground">Total add-ons</span><PackagePlus class="size-4 text-muted-foreground"/></div><div class="mt-3 text-2xl font-semibold">{{props.stats.total}}</div></div><div class="rounded-2xl border bg-card p-4 shadow-sm"><div class="flex justify-between"><span class="text-sm text-muted-foreground">Total stock</span><PackagePlus class="size-4 text-muted-foreground"/></div><div class="mt-3 text-2xl font-semibold">{{props.stats.stock}}</div></div></div><div class="rounded-2xl border bg-card shadow-sm"><div class="flex gap-3 border-b p-4"><div class="relative flex-1"><Search class="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input v-model="search" @keyup.enter="filter" class="pl-9" placeholder="Search add-on..."/></div><Button variant="secondary" @click="filter">Filter</Button><Button variant="ghost" @click="reset">Reset</Button></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-muted/40 text-left text-xs uppercase tracking-wide text-muted-foreground"><tr><th class="px-5 py-3">Name</th><th class="px-5 py-3">Price</th><th class="px-5 py-3">Stock</th><th class="px-5 py-3 text-right">Action</th></tr></thead><tbody class="divide-y"><tr v-for="x in props.addOns.data" :key="x.id" class="hover:bg-muted/20"><td class="px-5 py-4 font-medium"><Link :href="`/add-ons/${x.id}`" class="text-primary hover:underline">{{x.name}}</Link></td><td class="px-5 py-4 font-semibold">{{money(x.price)}}</td><td class="px-5 py-4">{{x.stock}}</td><td class="px-5 py-4"><div class="flex justify-end gap-1"><Button variant="ghost" size="icon" @click="edit(x)"><Pencil class="size-4"/></Button><Button variant="ghost" size="icon" @click="remove(x)"><Trash2 class="size-4 text-destructive"/></Button></div></td></tr><tr v-if="!props.addOns.data.length"><td colspan="4" class="px-5 py-16 text-center">No add-ons found</td></tr></tbody></table></div></div></div><div v-if="show" class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"><div class="w-full max-w-lg rounded-2xl border bg-background shadow-2xl"><div class="flex justify-between border-b p-5"><div><p class="text-sm font-medium text-primary">Add-on management</p><h2 class="text-xl font-semibold">{{title}}</h2></div><Button variant="ghost" size="icon" @click="close"><X class="size-4"/></Button></div><Form :key="key" :action="action" :method="method" class="space-y-4 p-5" @success="close" v-slot="{processing}"><div><Label>Name</Label><Input name="name" :default-value="editing?.name" required/></div><div><Label>Price</Label><Input name="price" type="number" min="0" :default-value="editing?.price" required/></div><div><Label>Stock</Label><Input name="stock" type="number" min="0" :default-value="editing?.stock" required/></div><div class="flex justify-end gap-2 border-t pt-4"><Button type="button" variant="ghost" @click="close">Cancel</Button><Button type="submit" :disabled="processing">{{editing?'Save changes':'Create add-on'}}</Button></div></Form></div></div></template>